arguments.command:
cd /app/data; cat > /tmp/load.py <<'E'
import gzip,glob,codecs
def raw(p):
    b=open(p,'rb').read()
    if b[:2]==b'\x1f\x8b': b=gzip.decompress(b)
    return b
E
python3 - <<'E'
import sys,glob,re,collections
sys.path.insert(0,'/tmp')
from load import raw
c=collections.Counter()
for p in sorted(glob.glob('*')):
    b=raw(p)
    enc='utf8'
    if b[:3]==b'\xef\xbb\xbf': enc='bom8'
    elif b[:2] in(b'\xff\xfe',b'\xfe\xff'): enc='bom16'
    c[(p.split('-')[0],enc)]+=1
    if enc=='bom16': t=b.decode('utf-16')
    else: t=b.decode('latin1')
    for l in t.split('\n'):
        if l.startswith('#') and not l.startswith('#LAYOUT') :
            c[(p.split('-')[0],re.sub(r'\d+','N',l.strip()))]+=1
        if l.startswith('#LAYOUT'): c[(p.split('-')[0],l.strip())]+=1
for k,v in sorted(c.items()): print(k,v)
E

