    "harbor": {"rec", "ref", "date", "weight", "state"},
}
SEP = {"east": ",", "lakeside": ",", "river": "\t", "west": ";", "harbor": "|"}
BASE_DATE = {"east": "ymd", "lakeside": "iso", "river": "mm/dd/yyyy",
             "west": "dd.mm.yyyy", "harbor": "iso"}


# ---------------------------------------------------------------- bytes/text
def read_bytes(path):
    with open(path, "rb") as f:
        b = f.read()
    while b[:2] == b"\x1f\x8b":
        b = gzip.decompress(b)
    return b


def decode(b):
    if b[:3] == b"\xef\xbb\xbf":
        return b[3:].decode("utf-8", "replace")
    if b[:2] in (b"\xff\xfe", b"\xfe\xff"):
        return b.decode("utf-16", "replace")
    enc = "utf-8"
    head = b[:2000].decode("latin-1")
    for line in head.splitlines()[:30]:
        m = re.match(r"\s*#\s*charset\s*:\s*([\w.\-]+)", line, re.I)
        if m:
            enc = m.group(1)
            break
    try:
        return b.decode(enc)
    except (LookupError, UnicodeDecodeError):
        return b.decode("utf-8", "replace")


# -------------------------------------------------------------------- values
def norm_status(s):
    return re.sub(r"[\s\-]+", "_", (s or "").strip().lower())


def counted(status):
    return status in ("delivered", "delivered_late")


def norm_type(s):
    s = (s or "").strip().lower()
    if s.startswith(("c", "a")):
        return "C"
    if s.startswith("v"):
        return "V"
    return "N"


def shipment_no(s):
    m = re.search(r"SH\D*(\d+)", s or "", re.I)
    return int(m.group(1)) if m else None


def norm_unit(u):
    u = (u or "").strip().lower().rstrip(".")
    return {"kgs": "kg", "kilogram": "kg", "kilograms": "kg", "gram": "g",
            "grams": "g", "lbs": "lb", "pound": "lb", "pounds": "lb",
            "ounce": "oz", "ounces": "oz"}.get(u, u)


def parse_number(s, decimal_comma=False):
    s = s.strip().replace(" ", "")
    if decimal_comma:
        s = s.replace(".", "").replace(",", ".")
    else:
        s = s.replace(",", "")
    return Decimal(s)


def parse_weight(text, unit, decimal_comma=False):
    """text may carry its own unit suffix; returns kg Decimal."""
    text = text.strip()
    m = re.match(r"^(.*?)\s*([A-Za-z]+)$", text)
    if m and norm_unit(m.group(2)) in KG:
        text, unit = m.group(1), m.group(2)
    return parse_number(text, decimal_comma) * KG[norm_unit(unit) or "kg"]


def parse_date(s, form):
    """Return a UTC date (or datetime converted to UTC date)."""
    s = s.strip()
    if "T" in s or ":" in s:
        return parse_iso_time(s)
    f = (form or "iso").strip().lower()
    if f == "serial" or re.fullmatch(r"\d{5}(\.\d+)?", s) and f == "serial":
        return dt.date(1899, 12, 30) + dt.timedelta(days=int(float(s)))
    parts = re.findall(r"[A-Za-z]+|\d+", s)
    if len(parts) == 3 and parts[1][:3].lower() in MONTHS:
        return dt.date(int(parts[2]), MONTHS[parts[1][:3].lower()], int(parts[0]))
    n = [int(p) for p in parts]
    if len(parts[0]) == 4:
        y, mo, d = n
    elif f in ("dmy", "dd-mm-yyyy", "dd/mm/yyyy", "dd.mm.yyyy"):
        d, mo, y = n
    elif f in ("mm/dd/yyyy", "mdy"):
        mo, d, y = n
    else:
        y, mo, d = n
    return dt.date(y, mo, d)


def parse_iso_time(s):
    s = s.strip()
    if s.endswith(("Z", "z")):
        s = s[:-1] + "+00:00"
    d = dt.datetime.fromisoformat(s)
    if d.tzinfo is not None:
        d = d.astimezone(dt.timezone.utc)
    return d.date()


# ------------------------------------------------------------------- readers
# Each reader yields (seq, [record]) with record = (type, number, date, kg, status)
def rec(typ, ref, date, kg, status):
    return (norm_type(typ), shipment_no(ref), date, kg, norm_status(status))


def find_seq(lines):
    for l in lines:
        m = re.match(r"\s*#\s*(?:\w+\s+export\s+)?seq\s*[:=]\s*(\d+)", l, re.I) \
            or re.match(r"\s*#SEQ\s+(\d+)", l)
        if m:
            return int(m.group(1))
    return None


def split_records(text):
    """Yield ('comment', line) or ('row', logical_line) honoring CSV quotes."""
    buf = None
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        if buf is None:
            if not line.strip():
                continue
            if line.startswith("#"):
                yield "comment", line
                continue
            buf = line
        else:
            buf += "\n" + line
        if buf.count('"') % 2 == 0:
            yield "row", buf
            buf = None
    if buf is not None:
        yield "row", buf


def read_delimited(depot, text):
    sep = SEP[depot]
    cols = COLUMNS[depot]
    quoted = depot in ("east", "lakeside")
    seq = None
    unit = "kg"
    datef = BASE_DATE[depot]
    dec_comma = depot == "west"
    hdr = None
    out = []
    comments = []
    for kind, line in split_records(text):
        if kind == "comment":
            comments.append(line)
            if seq is None:
                seq = find_seq([line])
            m = re.match(r"#\s*([A-Za-z ]+?)\s*:\s*(.*)$", line)
            if m:
                name, val = m.group(1).strip().lower(), m.group(2).strip()
                if name in ("unit", "weight unit") and val:
                    unit = norm_unit(val.split()[0])
                    if name == "weight unit":
                        dec_comma = "decimal comma" in val.lower() or depot == "west"
                elif name in ("dates", "date format", "date") and val:
                    datef = val.split()[0]
            continue
        if quoted:
            row = next(csv.reader([line], delimiter=sep))
        else:
            row = line.split(sep)
        low = [c.strip().lower() for c in row]
        if all(c in cols for c in low) and len(set(low)) == len(low):
            hdr = low
            continue
        if hdr is None:
            continue
        g = lambda *names: next((row[hdr.index(n)] for n in names
                                 if n in hdr and hdr.index(n) < len(row)), "")
        wcol = next((n for n in hdr if n in ("gross", "weight") or n.startswith("gross_")), None)
        row_unit = None
        if len(row) == len(hdr) + 1 and wcol is not None:
            wi = hdr.index(wcol)
            if norm_unit(row[wi + 1]) in KG:
                row_unit = norm_unit(row[wi + 1])
                row = row[:wi + 1] + row[wi + 2:]
            else:
                idx = [i for i, c in enumerate(row) if norm_unit(c) in KG]
                if idx:
                    row_unit = norm_unit(row[idx[0]])
                    del row[idx[0]]
        if len(row) != len(hdr):
            continue
        ref = g("id", "ref")
        if shipment_no(ref) is None:
            continue
        typ = g("type", "kind", "t", "typ", "rec")
        status = g("status", "state")
        if depot == "harbor":
            status = HARBOR_STATE.get(status.strip().upper(), status)
        shipped = g("shipped", "date")
        wtext = g(*(c for c in (wcol,) if c))
        wunit = row_unit or unit
        m = re.fullmatch(r"gross_(kg|g|lb|oz)", wcol or "")
        if m and not row_unit:
            wunit = m.group(1)
        if norm_type(typ) == "V":
            out.append(rec(typ, ref, None, None, ""))
            continue
        try:
            date = parse_date(shipped, datef)
            kg = parse_weight(wtext, wunit, dec_comma)
        except (ValueError, ArithmeticError):
            continue
        out.append(rec(typ, ref, date, kg, status))
    if seq is None:
        seq = find_seq(comments)
    return seq, out


def read_south(text):
    layouts = {
        "FW1": (42, dict(id=(0, 9), type=(9, 10), shipped=(10, 17), weight=(17, 25),
                         status=(25, 26)), "yyyyddd", Decimal("0.001")),
        "FW2": (43, dict(type=(0, 1), id=(1, 10), shipped=(10, 18), weight=(18, 26),
                         status=(26, 27)), "yyyymmdd", Decimal("0.01")),
        "FW3": (41, dict(id=(0, 9), shipped=(9, 16), type=(16, 17), weight=(17, 24),
                         status=(24, 25)), "yyyyddd", Decimal("0.1") * KG["lb"]),
    }
    by_len = {v[0]: k for k, v in layouts.items()}
    cur = None
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.rstrip("\r")
        if line.startswith("#LAYOUT"):
            cur = line.split()[1] if len(line.split()) > 1 else cur
            continue
        if line.startswith("#SEQ"):
            if seq is None:
                seq = int(line.split()[1])
            continue
        if line.startswith("#") or "\f" in line or not line.strip() \
                or line.lstrip().startswith("SOUTH DEPOT"):
            continue
        name = by_len.get(len(line), cur)
        if name not in layouts:
            continue
        n, f, dform, mult = layouts[name]
        line = line.ljust(n)
        v = {k: line[a:b] for k, (a, b) in f.items()}
        if shipment_no(v["id"]) is None:
            continue
        typ = norm_type(v["type"])
        if typ == "V":
            out.append(rec("V", v["id"], None, None, ""))
            continue
        try:
            s = v["shipped"]
            if dform == "yyyyddd":
                date = dt.date(int(s[:4]), 1, 1) + dt.timedelta(days=int(s[4:]) - 1)
            else:
                date = dt.date(int(s[:4]), int(s[4:6]), int(s[6:8]))
            kg = Decimal(int(v["weight"])) * mult
        except ValueError:
            continue
        out.append(rec(typ, v["id"], date, kg, FW_STATUS.get(v["status"].strip().upper(), "")))
    return seq, out


def read_north(text):
    seq = None
    out = []
    for line in text.split("\n"):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except ValueError:
            continue
        for o in (obj if isinstance(obj, list) else [obj]):
            if not isinstance(o, dict):
                continue
            if "meta" in o and "id" not in o:
                if seq is None and isinstance(o["meta"], dict):
                    seq = o["meta"].get("seq")
                continue
            if shipment_no(str(o.get("id", ""))) is None:
                continue
            typ = o.get("kind", "new")
            if norm_type(typ) == "V":
                out.append(rec("V", str(o["id"]), None, None, ""))
                continue
            kg = None
            for k, v in o.items():
                m = re.fullmatch(r"weight_(kg|g|lb|oz)", k.lower())
                if m and v is not None:
                    kg = parse_weight(str(v), m.group(1))
            if kg is None and "weight" in o:
                kg = parse_weight(str(o["weight"]), "kg")
            try:
                date = parse_iso_time(o["shipped_at"]) if "T" in o["shipped_at"] \
                    else parse_date(o["shipped_at"], "iso")
            except (KeyError, ValueError):
                continue
            out.append(rec(typ, str(o["id"]), date, kg, o.get("status", "")))
    return seq, out


def read_central(b):
    root = ET.fromstring(b)
    seq = root.get("seq")
    seq = int(seq) if seq and seq.isdigit() else None
    runit = norm_unit(root.get("weight-unit")) or "kg"
    out = []
    for sh in root.iter("shipment"):
        ref = sh.get("id", "")
        if shipment_no(ref) is None:
            continue
        typ = sh.get("type", "new")
        if norm_type(typ) == "V":
            out.append(rec("V", ref, None, None, ""))
            continue
        sv = sh.get("shipped")
        if sv is None:
            c = sh.find("shipped")
            sv = c.text if c is not None else None
        w = sh.find("weight")
        try:
            sv = sv.strip()
            date = parse_iso_time(sv) if "T" in sv else parse_date(sv, "iso")
            wu = norm_unit(w.get("unit")) or runit
            kg = parse_weight(w.text, wu)
        except (AttributeError, ValueError, ArithmeticError):
            continue
        st = sh.find("status")
        out.append(rec(typ, ref, date, kg, st.text if st is not None else ""))
    return seq, out


def read_export(depot, path):
    b = read_bytes(path)
    if depot == "central" or b.lstrip(b"\xef\xbb\xbf\xff\xfe\xfe")[:5] == b"<?xml":
        return read_central(b)
    text = decode(b)
    if depot == "south":
        return read_south(text)
    if depot == "north":
        return read_north(text)
    if depot in SEP:
        return read_delimited(depot, text)
    return None, []


# ---------------------------------------------------------------------- main
def main(data_dir, out_file):
    exports = {}
    for name in sorted(os.listdir(data_dir)):
        p = os.path.join(data_dir, name)
        if not os.path.isfile(p):
            continue
        depot = name.split("-")[0].lower()
        exports.setdefault(depot, [])
        try:
            seq, recs = read_export(depot, p)
        except Exception as e:  # unreadable export: report, keep going
            print("warning: %s: %s" % (name, e), file=sys.stderr)
            continue
        exports[depot].append((seq if seq is not None else -1, name, recs))

    corrections = resends = 0
    current = {}
    for depot, files in exports.items():
        cur = {}
        for _, _, recs in sorted(files, key=lambda x: (x[0], x[1])):
            for typ, num, date, kg, status in recs:
                if num is None:
                    continue
                if typ == "N":
                    if num in cur:
                        resends += 1
                    else:
                        cur[num] = (date, kg, status)
                elif typ == "C":
                    cur[num] = (date, kg, status)
                    corrections += 1
                else:
                    cur.pop(num, None)
                    corrections += 1
        current[depot] = cur

    rank = lambda d: ORDER.index(d) if d in ORDER else len(ORDER)
    owners = {}
    for depot in sorted(current, key=rank):
        for num in current[depot]:
            owners.setdefault(num, []).append(depot)
    handovers = sum(1 for o in owners.values() if len(o) > 1)

    depots = {d: [0, Decimal(0)] for d in exports}
    months = {}
    for num, owner in owners.items():
        date, kg, status = current[owner[0]][num]
        if not counted(status) or date is None or kg is None:
            continue
        depots[owner[0]][0] += 1
        depots[owner[0]][1] += kg
        m = months.setdefault("%04d-%02d" % (date.year, date.month), [0, Decimal(0)])
        m[0] += 1
        m[1] += kg

    q = lambda x: float(x.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))
    result = {
        "depots": {d: {"shipments": v[0], "total_kg": q(v[1])}
                   for d, v in sorted(depots.items())},
        "months": {k: {"shipments": v[0], "total_kg": q(v[1])}
                   for k, v in sorted(months.items())},
        "corrections_applied": corrections,
        "resends_dropped": resends,
        "handovers": handovers,
    }
    with open(out_file, "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
